import json
from pathlib import Path

groups = {}
def add(group, method, path, body=None, form=None, public=False, legacy=False, note='', files=()):
    headers = []
    if legacy and method not in ('GET', 'HEAD'):
        headers.append({'key': 'X-CSRFToken', 'value': '{{csrfToken}}'})
    if '/clinics/' in path and any(x in path for x in ('context/', 'patients/', 'memberships/{{membershipId}}/', 'invitations/{{invitationId}}/', 'invitations/|')):
        headers.append({'key': 'X-Clinic-ID', 'value': '{{clinicId}}'})
    if path == '/api/v1/clinics/invitations/' and method == 'POST':
        headers.append({'key': 'X-Clinic-ID', 'value': '{{clinicId}}'})
    req = {'method': method, 'header': headers, 'url': '{{baseUrl}}' + path, 'description': note}
    if public or legacy:
        req['auth'] = {'type': 'noauth'}
    if body is not None:
        req['body'] = {'mode': 'raw', 'raw': json.dumps(body, ensure_ascii=False, indent=2), 'options': {'raw': {'language': 'json'}}}
    if form is not None:
        entries = [{'key': k, 'value': str(v), 'type': 'text'} for k, v in form.items()]
        entries += [{'key': key, 'type': 'file', 'src': []} for key in files]
        req['body'] = {'mode': 'formdata' if files else 'urlencoded', 'formdata' if files else 'urlencoded': entries}
    item = {'name': method + ' ' + path, 'request': req}
    if path in ('/api/v1/auth/login/', '/api/v1/auth/refresh/', '/api/v1/auth/session/'):
        item['event'] = [{'listen': 'test', 'script': {'type': 'text/javascript', 'exec': ['if (pm.response.code === 200) { const data = pm.response.json(); if (data.access) pm.collectionVariables.set("accessToken", data.access); }']}}]
    groups.setdefault(group, []).append(item)

