lines = ['# Endpoints de SmileManager para Postman', '', 'La colección importable es `SmileManager.postman_collection.json`. Se generó a partir de las rutas y vistas del proyecto. Las peticiones siguientes usan las mismas variables de colección.', '', '## Preparación', '', '1. Importa el JSON en Postman. En Variables, configura `baseUrl`, `username`, `password` y los ID existentes. La fecha de la cita debe ser futura y el teléfono y correo del paciente deben ser únicos para el médico.', '2. Ejecuta `POST /api/v1/auth/login/`. El script guarda automáticamente el access token en `accessToken`. Postman debe conservar la cookie `smile_refresh` para session, refresh y logout. En refresh también se actualiza `accessToken`.', '3. Para las rutas de clínicas configura `clinicId` con el UUID y usa una cuenta con la membresía y capacidad necesarias. Algunas acciones requieren rol de administrador de clínica o de backoffice. Las rutas clínicas globales del backoffice devuelven acceso denegado por diseño.', '4. Para las rutas web inicia sesión por `/sesiones/login/`: haz GET a esa página, copia la cookie `csrftoken` a `csrfToken`, y después ejecuta el POST de login. Mantén habilitado el almacenamiento de cookies de Postman. Las peticiones web modificadoras incluyen `X-CSRFToken`. La sesión web y el token API son independientes.', '5. En las peticiones de archivos, selecciona archivos reales en Body > form-data. Para historial médico y odontograma primero consulta el recurso y usa su `version` actual; para uno nuevo se usa 0.', '', 'Los ID son ejemplos: deben existir y ser accesibles por el usuario. Las rutas web suelen devolver HTML o redirecciones; las exportaciones y archivos devuelven contenido binario. Envíos de correo, cambios de estado, análisis y eliminaciones producen efectos reales. Usa datos de prueba.', '', 'Los métodos documentados son los métodos funcionales de cada vista; DRF también puede responder OPTIONS y HEAD en rutas compatibles. Django Admin genera rutas adicionales dinámicamente según los modelos registrados y permisos; `/admin/` permite acceder a ellas. `/app` acepta rutas hijas de la aplicación React.', '']
for group, items in groups.items():
    lines += ['## '+group, '']
    for item in items:
        req = item['request']
        lines += ['### '+item['name'], '', '```http', req['method']+' '+req['url']]
        if req.get('auth', {}).get('type') != 'noauth': lines.append('Authorization: Bearer {{accessToken}}')
        for header in req['header']: lines.append(header['key']+': '+header['value'])
        b = req.get('body')
        if b and b['mode']=='raw': lines += ['Content-Type: application/json', '', b['raw']]
        elif b:
            lines += ['Content-Type: '+('multipart/form-data (seleccionado por Postman)' if b['mode']=='formdata' else 'application/x-www-form-urlencoded'), '']
            for entry in b[b['mode']]: lines.append(entry['key']+' = '+('[seleccionar archivo]' if entry.get('type')=='file' else entry['value']))
        lines += ['```', '']
        if req['description']: lines += [req['description'], '']
Path('ENDPOINTS_POSTMAN.md').write_text('\n'.join(lines),encoding='utf-8')
